WITH parsed AS (SELECT id, customer_id, ship_to, attributes, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, ARRAY_CONTAINS(coupon_codes, 'VIP') AS used_vip, attributes['utm_source'] AS utm_source, SIZE(items) AS num_items FROM carts) SELECT id, customer_id, has_welcome_code, num_items, NTILE(10) OVER (PARTITION BY customer_id ORDER BY num_items ASC, id ASC) AS num_items_bucket, SUM(num_items) OVER (ORDER BY num_items ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_num_items FROM parsed WHERE num_items <= 2;
